"""Apply manually checked source-pixel findings; preserve stable IDs and raw sources."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[4]
PATH = ROOT/'scripts/atlas/corrections/a97001.json'
data = json.loads(PATH.read_text(encoding='utf-8'))
pages = {p['page']: (s['id'],p) for f in (ROOT/'data/atlas/a97001/sections').glob('*.json')
         for s in [json.loads(f.read_text(encoding='utf-8'))] for p in s['pages']}

def patch(page, collection, index, fields, ids):
    section, obj = pages[page]
    item = obj[collection][index]
    data['structure'].append({'page':page,'section':section,'op':'set','collection':collection,
                             'id':item['id'],'fields':fields,'audit_ids':ids,
                             'why':'Повторная сверка с пикселями original97001.pdf; '+', '.join(ids)})

def text(page, index, replacements, ru, ids, **more):
    item = pages[page][1]['items'][index]
    pointed = item['he_niqqud']
    for before, after in replacements:
        assert before in pointed, (page,index,before)
        pointed = pointed.replace(before,after)
    patch(page,'items',index,{'he_niqqud':pointed,'ru':ru,**more},ids)

